### RigUI Script generated by Bone Layers Addon ###

import bpy

rig_id = "Mannequin"


class BLOP_PT_rigui_Mannequin(bpy.types.Panel):
	bl_space_type = 'VIEW_3D'
	bl_region_type = 'UI'
	bl_category = 'Item'
	bl_label = "Rig UI"
	bl_idname = "BLOP_PT_rigui_Mannequin"

	@classmethod
	def poll(self, context):
		try:
			return (context.active_object.data.get("rig_id") == rig_id)
		except (AttributeError, KeyError, TypeError):
			return False

	def draw(self, context):
		layout = self.layout
		col = layout.column()
		collection = bpy.data.armatures["Armature_Mannequin"].collections


		row = col.row()
		row.prop(collection["Layer 6 - ROOT"], 'is_visible', toggle=True, text='ROOT')

		row = col.row()
		row.prop(collection["Layer 8 - TORSO"], 'is_visible', toggle=True, text='TORSO')
		row.prop(collection["Layer 9 - TORSO-TWEAK"], 'is_visible', toggle=True, text='TORSO-TWEAK')

		row = col.row()
		row.prop(collection["Layer 11 - ARM-FK.L"], 'is_visible', toggle=True, text='ARM-FK.L')
		row.prop(collection["Layer 13 - ARM-FK.R"], 'is_visible', toggle=True, text='ARM-FK.R')

		row = col.row()
		row.prop(collection["Layer 12 - ARM-IK.L"], 'is_visible', toggle=True, text='ARM-IK.L')
		row.prop(collection["Layer 14 - ARM-IK.R"], 'is_visible', toggle=True, text='ARM-IK.R')

		row = col.row()
		row.prop(collection["Layer 15 - ARM-TWEAK"], 'is_visible', toggle=True, text='ARM-TWEAK')

		row = col.row()
		row.prop(collection["Layer 16 - HANDS-MASTER"], 'is_visible', toggle=True, text='HANDS-MASTER')
		row.prop(collection["Layer 17 - HANDS"], 'is_visible', toggle=True, text='HANDS')
		row.prop(collection["Layer 18 - HANDS-TWEAK"], 'is_visible', toggle=True, text='HANDS-TWEAK')
		
		row = col.row()
		row = col.row()
		row.prop(collection["Layer 19 - LEG-IK.L"], 'is_visible', toggle=True, text='LEG-IK.L')
		row.prop(collection["Layer 21 - LEG-IK.R"], 'is_visible', toggle=True, text='LEG-IK.R')

		row = col.row()
		row.prop(collection["Layer 20 - LEG-FK.L"], 'is_visible', toggle=True, text='LEG-FK.L')
		row.prop(collection["Layer 22 - LEG-FK.R"], 'is_visible', toggle=True, text='LEG-FK.R')

		row = col.row()
		row.prop(collection["Layer 23 - LEG-TWEAK"], 'is_visible', toggle=True, text='LEG-TWEAK')



